import { useId, useRef, type KeyboardEvent, type ReactNode } from "react";
import "./TabStrip.css";

export interface Tab {
  id: string;
  label: string;
}

export interface TabStripProps {
  tabs: readonly Tab[];
  selected: string;
  onSelect: (id: string) => void;
  children: ReactNode;
}

export function TabStrip({ tabs, selected, onSelect, children }: TabStripProps) {
  const baseId = useId();
  const buttonRefs = useRef<Map<string, HTMLButtonElement>>(new Map());

  const selectedIndex = tabs.findIndex((tab) => tab.id === selected);
  // Roving tabindex: the selected tab is the single tab stop in the strip.
  // If the selected id is unknown, fall back to the first tab so the strip stays reachable.
  const tabStopIndex = selectedIndex >= 0 ? selectedIndex : 0;

  const tabDomId = (id: string) => `${baseId}-tab-${id}`;
  const panelDomId = `${baseId}-panel`;

  const activate = (index: number) => {
    const tab = tabs[index];
    if (!tab) return;
    onSelect(tab.id);
    buttonRefs.current.get(tab.id)?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const last = tabs.length - 1;
    let next: number;

    switch (event.key) {
      case "ArrowRight":
        next = index === last ? 0 : index + 1;
        break;
      case "ArrowLeft":
        next = index === 0 ? last : index - 1;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = last;
        break;
      default:
        return;
    }

    event.preventDefault();
    activate(next);
  };

  return (
    <div className="tab-strip">
      <div role="tablist" className="tab-strip__list">
        {tabs.map((tab, index) => {
          const isSelected = tab.id === selected;
          return (
            <button
              key={tab.id}
              ref={(element) => {
                if (element) {
                  buttonRefs.current.set(tab.id, element);
                } else {
                  buttonRefs.current.delete(tab.id);
                }
              }}
              type="button"
              role="tab"
              id={tabDomId(tab.id)}
              className="tab-strip__tab"
              aria-selected={isSelected}
              aria-controls={panelDomId}
              tabIndex={index === tabStopIndex ? 0 : -1}
              onClick={() => onSelect(tab.id)}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {tab.label}
            </button>
          );
        })}
      </div>

      <div
        role="tabpanel"
        id={panelDomId}
        className="tab-strip__panel"
        aria-labelledby={selectedIndex >= 0 ? tabDomId(selected) : undefined}
        tabIndex={0}
      >
        {children}
      </div>
    </div>
  );
}
