}

[data-theme="night"] .tab-strip,
.tab-strip[data-theme="night"] {
  --ts-text: #e6e8ec;
  --ts-muted: #9aa1ab;
  --ts-accent: #8ab4f8;
  --ts-line: #2e333b;
  --ts-hover: rgba(230, 232, 236, 0.08);
  --ts-focus: #8ab4f8;
}

@media (prefers-color-scheme: dark) {
  .tab-strip:not([data-theme]),
  .tab-strip[data-theme="auto"] {
    --ts-text: #e6e8ec;
    --ts-muted: #9aa1ab;
    --ts-accent: #8ab4f8;
    --ts-line: #2e333b;
    --ts-hover: rgba(230, 232, 236, 0.08);
    --ts-focus: #8ab4f8;
  }
}

.tab-strip__list {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--ts-line);
  overflow-x: auto;
  scrollbar-width: none;
}

.tab-strip__list::-webkit-scrollbar {
  display: none;
}

.tab-strip__tab {
  appearance: none;
  background: none;
  border: 0;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  padding: 10px 14px;
  border-radius: 6px 6px 0 0;
  color: var(--ts-muted);
  font: inherit;
  white-space: nowrap;
  cursor: pointer;
  transition:
    color 0.15s ease,
    background-color 0.15s ease,
    border-color 0.15s ease;
}

.tab-strip__tab:hover {
  color: var(--ts-text);
  background-color: var(--ts-hover);
}

.tab-strip__tab[aria-selected="true"] {
  color: var(--ts-accent);
  border-bottom-color: var(--ts-accent);
  font-weight: 600;
}

.tab-strip__tab:focus-visible,
.tab-strip__panel:focus-visible {
  outline: 2px solid var(--ts-focus);
  outline-offset: 2px;
}

.tab-strip__panel {
  flex: 1;
  min-height: 0;
}

@media (prefers-reduced-motion: reduce) {
  .tab-strip__tab {
    transition: none;
  }
}
